    type Workspace =
        ::sce_rust_runtime::Workspace<{ ::sce_rust_runtime::state_scratch(1) }, 1, 6, 0>;
    type RunStore = ::sce_rust_runtime::RunStore<1, 0, 0>;
    type Configuration = StatechartHostInvokerConfiguration;

